'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var hasProp = require( '@stdlib/assert/has-property' );
var isString = require( '@stdlib/assert/is-string' );
var Autosize = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Autosize, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `type` property', function test( t ) {
	var v;

	v = new Autosize();
	t.strictEqual( hasOwnProp( v, 'type' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'type' ), true, 'returns expected value' );
	t.strictEqual( isString( v.type ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor throws an error if provided an invalid `type` option', function test( t ) {
	var values;
	var i;

	values = [
		'beep',
		'boop',
		'invalid',
		'PAD',
		'FIT',
		5,
		NaN,
		null,
		void 0,
		true,
		false,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var autosize = new Autosize({ // eslint-disable-line no-unused-vars
				'type': value
			});
		};
	}
});

tape( 'the constructor returns an instance having a `type` property which throws an error if set to an invalid value', function test( t ) {
	var values;
	var i;

	values = [
		'beep',
		'boop',
		'invalid',
		'PAD',
		'FIT',
		5,
		NaN,
		null,
		void 0,
		true,
		false,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var autosize = new Autosize();
			autosize.type = value;
		};
	}
});

tape( 'the constructor returns an instance having a `type` property which returns the autosize type', function test( t ) {
	var autosize;

	autosize = new Autosize();
	t.strictEqual( autosize.type, 'pad', 'returns expected value' );

	autosize = new Autosize({
		'type': 'fit'
	});
	t.strictEqual( autosize.type, 'fit', 'returns expected value' );

	autosize = new Autosize({
		'type': 'fit-x'
	});
	t.strictEqual( autosize.type, 'fit-x', 'returns expected value' );

	autosize = new Autosize({
		'type': 'fit-y'
	});
	t.strictEqual( autosize.type, 'fit-y', 'returns expected value' );

	autosize = new Autosize({
		'type': 'none'
	});
	t.strictEqual( autosize.type, 'none', 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `type` property which can be set to a valid autosize method', function test( t ) {
	var autosize;

	autosize = new Autosize();

	autosize.type = 'fit';
	t.strictEqual( autosize.type, 'fit', 'returns expected value' );

	autosize.type = 'fit-x';
	t.strictEqual( autosize.type, 'fit-x', 'returns expected value' );

	autosize.type = 'fit-y';
	t.strictEqual( autosize.type, 'fit-y', 'returns expected value' );

	autosize.type = 'none';
	t.strictEqual( autosize.type, 'none', 'returns expected value' );

	autosize.type = 'pad';
	t.strictEqual( autosize.type, 'pad', 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which emits an event when the `type` property is set to a new value', function test( t ) {
	var autosize;
	var count;

	autosize = new Autosize();
	count = 0;

	autosize.on( 'change', onChange );

	autosize.type = 'fit';
	t.strictEqual( count, 1, 'returns expected value' );

	autosize.type = 'none';
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to the same value should not emit an event:
	autosize.type = 'none';
	t.strictEqual( count, 2, 'returns expected value' );

	t.end();

	function onChange() {
		count += 1;
	}
});
